{"cmd":"node --input-type=module - <<'EOF'
import { execFile } from 'node:child_process';
import { writeFile } from 'node:fs/promises';

const letters = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ';
const codes = [];
for (const a of letters) {
  for (const b of letters) {
    for (const c of letters) {
      codes.push(a + b + c);
    }
  }
}

const executable = '/workspace/dataset/test10_executable';
const concurrency = 64;
let index = 0;
const results = [];
let completed = 0;

function runOne(code) {
  return new Promise((resolve) => {
    execFile(executable, ['--amount=1.2345', `--currency=${code}`], { encoding: 'utf8', maxBuffer: 1024 * 1024 }, (error, stdout, stderr) => {
      if (!error) {
        results.push({ code, output: stdout.replace(/\n$/, '') });
      }
      completed += 1;
      if (completed % 1000 === 0) {
        console.error(`progress ${completed}/${codes.length}`);
      }
      resolve();
    });
  });
}

async function worker() {
  while (true) {
    const current = index;
    index += 1;
    if (current >= codes.length) {
      return;
    }
    await runOne(codes[current]);
  }
}

await Promise.all(Array.from({ length: concurrency }, () => worker()));
results.sort((a, b) => a.code.localeCompare(b.code));
await writeFile('/tmp/test10_currency_probe.json', JSON.stringify(results, null, 2));
console.log(`valid=${results.length}`);
console.log(results.slice(0, 20).map((entry) => `${entry.code}:${entry.output}`).join('\n'));
EOF","workdir":"/workspace","yield_time_ms":1000,"max_output_tokens":12000,"tty":false}

